import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Feishu (Lark) Channel Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/channels/feishu.md","filePath":"integrations/channels/feishu.md","lastUpdated":1790952322000}'),s={name:"integrations/channels/feishu.md"};function i(r,e,l,h,c,d){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="feishu-lark-channel-configuration" tabindex="-1">Feishu (Lark) Channel Configuration <a class="header-anchor" href="#feishu-lark-channel-configuration" aria-label="Permalink to &quot;Feishu (Lark) Channel Configuration&quot;">​</a></h1><p>Connect your Memoh bot to Feishu (Lark) via the Open Platform, so enterprise bots can interact with users in groups and private chats.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu Open Platform</a> account that can create custom apps.</li><li>A Memoh bot; channels are configured from its <strong>Platforms</strong> tab.</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-in-the-feishu-console-create-a-custom-app" tabindex="-1">1. In the Feishu console, create a custom app <a class="header-anchor" href="#_1-in-the-feishu-console-create-a-custom-app" aria-label="Permalink to &quot;1. In the Feishu console, create a custom app&quot;">​</a></h3><ol><li>Go to the <a href="https://open.feishu.cn/app" target="_blank" rel="noreferrer">Feishu Open Platform</a> and log in.</li><li>Click <strong>Create Custom App</strong>, enter a name and description, then click <strong>Create</strong>.</li><li>In the left sidebar, go to <strong>App Settings</strong> &gt; <strong>Credentials &amp; Basic Info</strong>.</li><li>Copy your <strong>App ID</strong> and <strong>App Secret</strong>.</li></ol><h3 id="_2-in-the-feishu-console-enable-the-bot-capability" tabindex="-1">2. In the Feishu console, enable the bot capability <a class="header-anchor" href="#_2-in-the-feishu-console-enable-the-bot-capability" aria-label="Permalink to &quot;2. In the Feishu console, enable the bot capability&quot;">​</a></h3><p>Go to <strong>Capabilities</strong> &gt; <strong>Bot</strong> and click <strong>Enable Bot</strong>.</p><h3 id="_3-in-the-feishu-console-configure-permissions" tabindex="-1">3. In the Feishu console, configure permissions <a class="header-anchor" href="#_3-in-the-feishu-console-configure-permissions" aria-label="Permalink to &quot;3. In the Feishu console, configure permissions&quot;">​</a></h3><ol><li>Go to <strong>Capabilities</strong> &gt; <strong>Permissions</strong>.</li><li>Search for and enable the following permissions (at minimum): <ul><li><code>im:message</code> (receive and send messages)</li><li><code>im:chat</code> (access group chat information)</li></ul></li><li>Click <strong>Apply for Permissions</strong> if required by your organization.</li></ol><h3 id="_4-in-memoh-add-the-feishu-channel-default-long-connection" tabindex="-1">4. In Memoh, add the Feishu channel (default: long connection) <a class="header-anchor" href="#_4-in-memoh-add-the-feishu-channel-default-long-connection" aria-label="Permalink to &quot;4. In Memoh, add the Feishu channel (default: long connection)&quot;">​</a></h3><ol><li>Go to your bot&#39;s <strong>Platforms</strong> tab and add a <strong>Feishu</strong> channel.</li><li>Keep <strong>Inbound Mode</strong> at its default: <code>websocket</code>.</li><li>Fill in your <strong>App ID</strong> and <strong>App Secret</strong>; if you use international Lark, switch <strong>Region</strong> to <code>lark</code>.</li><li>Click <strong>Save</strong>. Messages arrive over Feishu&#39;s <strong>WebSocket long connection</strong> — no public callback URL and no event-subscription setup needed.</li></ol><h3 id="_5-optional-switch-to-webhook-mode" tabindex="-1">5. Optional: switch to webhook mode <a class="header-anchor" href="#_5-optional-switch-to-webhook-mode" aria-label="Permalink to &quot;5. Optional: switch to webhook mode&quot;">​</a></h3><p>Choose this only when your server is publicly reachable and you prefer event callbacks.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This mode round-trips between Memoh and the Feishu console: Memoh generates a callback URL that you paste back into <strong>Event Subscriptions</strong>, so keep the Feishu console open.</p></div><ol><li>In Memoh, set <strong>Inbound Mode</strong> to <code>webhook</code>; besides the <strong>App ID</strong> and <strong>App Secret</strong>, also fill in the <strong>Encrypt Key</strong> and <strong>Verification Token</strong> matching your Event Subscriptions settings in the Feishu console.</li><li>Click <strong>Save</strong>. Memoh generates a <strong>Webhook Callback URL</strong> — copy it.</li><li>In the Feishu console, go to <strong>App Settings</strong> &gt; <strong>Event Subscriptions</strong>, paste the URL into the <strong>Verification URL</strong> field, and save.</li><li>Add events like <strong>Receive Message</strong> (<code>im.message.receive_v1</code>).</li></ol><blockquote><p>Official guide: <a href="https://open.feishu.cn/document/client-docs/bot-v3/add-custom-bot" target="_blank" rel="noreferrer">Feishu Custom Bot Guide</a></p></blockquote><h3 id="_6-in-the-feishu-console-publish-your-app" tabindex="-1">6. In the Feishu console, publish your app <a class="header-anchor" href="#_6-in-the-feishu-console-publish-your-app" aria-label="Permalink to &quot;6. In the Feishu console, publish your app&quot;">​</a></h3><ol><li>Go to <strong>App Release</strong> &gt; <strong>Version Management &amp; Release</strong>.</li><li>Click <strong>Create a Version</strong>, fill in the details, and submit for approval.</li><li>Once approved and published, the bot is ready to use in your tenant.</li></ol><h2 id="credentials" tabindex="-1">Credentials <a class="header-anchor" href="#credentials" aria-label="Permalink to &quot;Credentials&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>App ID</strong></td><td>From <strong>App Settings</strong> &gt; <strong>Credentials &amp; Basic Info</strong> in the Feishu console.</td></tr><tr><td><strong>App Secret</strong></td><td>From the same <strong>Credentials &amp; Basic Info</strong> page.</td></tr><tr><td><strong>Region</strong></td><td>Switch to <code>lark</code> if you use international Lark.</td></tr><tr><td><strong>Inbound Mode</strong></td><td><code>websocket</code> (default, long connection) or <code>webhook</code>.</td></tr><tr><td><strong>Encrypt Key</strong></td><td>Webhook mode only; must match your Event Subscriptions settings in the Feishu console.</td></tr><tr><td><strong>Verification Token</strong></td><td>Webhook mode only; must match your Event Subscriptions settings in the Feishu console.</td></tr></tbody></table><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Open a private chat with the bot in Feishu and send <code>/help</code>. If the bot replies with its command list, the channel is working.</p><h2 id="group-chats" tabindex="-1">Group chats <a class="header-anchor" href="#group-chats" aria-label="Permalink to &quot;Group chats&quot;">​</a></h2><p>Feishu group chats are supported. Add the bot to a group and @mention it to talk to it there.</p><h2 id="disable-and-rotate-credentials" tabindex="-1">Disable and rotate credentials <a class="header-anchor" href="#disable-and-rotate-credentials" aria-label="Permalink to &quot;Disable and rotate credentials&quot;">​</a></h2><p>You can disable or remove this channel at any time from the bot&#39;s <strong>Platforms</strong> tab. To rotate credentials, update the fields (such as <strong>App Secret</strong>) and save.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="app-not-published" tabindex="-1">The channel is configured but the bot does not respond <a class="header-anchor" href="#app-not-published" aria-label="Permalink to &quot;The channel is configured but the bot does not respond {#app-not-published}&quot;">​</a></h3><p>A custom app must be published first: in the Feishu console, go to <strong>App Release</strong> &gt; <strong>Version Management &amp; Release</strong>, create a version, and submit it for approval. Once approved and published, the bot is ready to use in your tenant.</p><h3 id="permission-approval" tabindex="-1">Enabling permissions requires an approval <a class="header-anchor" href="#permission-approval" aria-label="Permalink to &quot;Enabling permissions requires an approval {#permission-approval}&quot;">​</a></h3><p>Some organizations require an approval flow for app permissions: click <strong>Apply for Permissions</strong> under <strong>Capabilities</strong> &gt; <strong>Permissions</strong> to submit the request.</p>',33)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
